#pragma once

/**
 * @file idc.h
 * @brief Support types for asynchronous inter-database communication (IDC).
 *
 * Receiver bindings generated by `spacetime generate --bindings module --lang cpp`
 * describe another module's reducers using the types in this header.
 */

#include <array>
#include <cstddef>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include "spacetimedb/bsatn/types.h"
#include "spacetimedb/bsatn/traits.h"
#include "spacetimedb/bsatn/type_extensions.h"

namespace SpacetimeDB {

/**
 * @brief The identity of a database that runs a particular receiver module.
 *
 * Each set of receiver bindings defines its own `Identity` as
 * `RemoteIdentity<module_tag>`, so the compiler rejects sending one module's
 * reducer to an identity meant for another. In the database and to clients,
 * a column of this type is an ordinary `Identity`.
 *
 * A plain `Identity` converts to it only explicitly:
 * @code
 * game_world::Identity world{ctx.sender()};
 * @endcode
 */
template<typename ModuleTag>
class RemoteIdentity {
public:
    using module_tag = ModuleTag;

    RemoteIdentity() = default;
    explicit RemoteIdentity(const Identity& identity) : identity_(identity) {}

    const Identity& identity() const { return identity_; }
    explicit operator const Identity&() const { return identity_; }

    std::string to_hex_string() const { return identity_.to_hex_string(); }
    std::string to_string() const { return identity_.to_string(); }

    friend bool operator==(const RemoteIdentity& a, const RemoteIdentity& b) { return a.identity_ == b.identity_; }
    friend bool operator!=(const RemoteIdentity& a, const RemoteIdentity& b) { return !(a == b); }
    friend bool operator<(const RemoteIdentity& a, const RemoteIdentity& b) { return a.identity_ < b.identity_; }

private:
    Identity identity_;
};

template<typename T>
struct is_remote_identity : std::false_type {};

template<typename ModuleTag>
struct is_remote_identity<RemoteIdentity<ModuleTag>> : std::true_type {};

template<typename T>
inline constexpr bool is_remote_identity_v = is_remote_identity<std::remove_cv_t<T>>::value;

namespace bsatn {

template<typename ModuleTag>
struct bsatn_traits<::SpacetimeDB::RemoteIdentity<ModuleTag>> {
    static void serialize(Writer& writer, const ::SpacetimeDB::RemoteIdentity<ModuleTag>& value) {
        bsatn_traits<::SpacetimeDB::Identity>::serialize(writer, value.identity());
    }

    static ::SpacetimeDB::RemoteIdentity<ModuleTag> deserialize(Reader& reader) {
        return ::SpacetimeDB::RemoteIdentity<ModuleTag>(bsatn_traits<::SpacetimeDB::Identity>::deserialize(reader));
    }

    static AlgebraicType algebraic_type() {
        return bsatn_traits<::SpacetimeDB::Identity>::algebraic_type();
    }
};

template<typename ModuleTag>
struct algebraic_type_of<::SpacetimeDB::RemoteIdentity<ModuleTag>> {
    static AlgebraicType get() {
        return bsatn_traits<::SpacetimeDB::Identity>::algebraic_type();
    }
};

} // namespace bsatn

/**
 * @brief A reducer handle generated from a receiver module.
 *
 * Generated handles are empty structs in the bindings' `reducers` namespace:
 * @code
 * struct receive_ping {
 *     static constexpr std::string_view name = "receive_ping";
 *     static constexpr std::string_view signature_hash = "...";
 *     using identity_type = ::game_world::Identity;
 *     using param_types = std::tuple<std::string>;
 *     static constexpr std::array<std::string_view, 1> param_names{"body"};
 * };
 * @endcode
 *
 * `name` is the reducer's canonical name in the receiver, `signature_hash` is the
 * hex-encoded hash the receiver checks before running a call, and `param_names`
 * and `param_types` list the reducer's parameters in order.
 */
template<typename H>
concept RemoteReducerHandle = requires {
    { H::name } -> std::convertible_to<std::string_view>;
    { H::signature_hash } -> std::convertible_to<std::string_view>;
    typename H::identity_type;
    typename H::param_types;
    H::param_names;
} && is_remote_identity_v<typename H::identity_type>
  && (std::tuple_size_v<typename H::param_types> == std::tuple_size_v<std::remove_cv_t<decltype(H::param_names)>>);

namespace detail {

/// Index of the receiver parameter named `name`, or `param_count` if there is none.
template<RemoteReducerHandle H>
constexpr std::size_t remote_param_index(std::string_view name) {
    constexpr std::size_t count = std::tuple_size_v<typename H::param_types>;
    for (std::size_t i = 0; i < count; ++i) {
        if (H::param_names[i] == name) {
            return i;
        }
    }
    return count;
}

} // namespace detail

} // namespace SpacetimeDB
